import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl library API design principles","description":"","frontmatter":{},"headers":[],"relativePath":"handl/explanation/ac-lib-api-design-principles.md","filePath":"vendored/handl/explanation/ac-lib-api-design-principles.md"}`),a={name:`handl/explanation/ac-lib-api-design-principles.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-library-api-design-principles" tabindex="-1">handl library API design principles <a class="header-anchor" href="#handl-library-api-design-principles" aria-label="Permalink to “handl library API design principles”">​</a></h1><p>These principles guide the public API of the <code>handl</code> facade and the <code>handl-*</code> library crates.</p><ul><li><p><strong>Modularity.</strong> Functionality is split into focused crates with narrow, stable boundaries. Each crate exposes one thing well, and the facade composes them behind feature flags.</p></li><li><p><strong>Type-safety.</strong> Errors are surfaced as types, not strings. Every fallible operation returns a <code>Result</code> with a dedicated error type, and types encode invariants at the boundary.</p></li><li><p><strong>Composability.</strong> Small, single-purpose types compose through traits and modules. Higher-level APIs are built from lower-level primitives, and hosts can swap implementations without rewriting call sites.</p></li><li><p><strong>Tree-shakeability.</strong> Each major subsystem lives behind a Cargo feature and is re-exported conditionally. Disable default features and enable only what your host uses; unused crates and symbols are not compiled or linked.</p></li><li><p><strong>Runtime-agnostic core.</strong> The AST, schema, and VM know nothing about I/O, formats, or control flow. The host provides all behavior through traits, so the library runs anywhere the host can be implemented.</p></li><li><p><strong>Feature-gated re-exports.</strong> The <code>handl</code> facade mirrors the crate graph with feature flags. No feature means no dependency, so hosts pay only for the capabilities they opt in to.</p></li><li><p><strong>Ergonomics.</strong> Low-level crates expose the full API; <code>handl</code> provides a <code>prelude</code> and grouped re-exports for the common case. Hosts that need control can import from individual crates directly.</p></li><li><p><strong>Backward compatibility.</strong> Public types are versioned and additive. New functionality is added behind new features or new modules; existing paths are not re-interpreted.</p></li><li><p><strong>Predictable allocation.</strong> Hot paths accept borrowed data and return owned results only when necessary. Callers can reuse buffers and control when values are materialized.</p></li></ul>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};